<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref } from 'vue'
import { api,errorText,sessionEpoch } from '../api'
import { availableTaskCompanies,departmentsForCompany,listItems } from '../domain'
import type { Row } from '../domain'
import { useAuth } from '../stores/auth'
import { parseTaskRows } from '../task-import'
const auth=useAuth(),source=ref(''),rows=ref<Row[]>([]),departments=ref<Row[]>([]),directory=ref<Row[]>([]),companyId=ref<string|number|null>(auth.me?.companyId??null),host=ref<string|number|null>(null),deadline=ref(''),busy=ref(false),locked=ref(false),error=ref('')
const companies=computed(()=>availableTaskCompanies(auth.me?.role??'',auth.me?.companyId,directory.value)),hosts=computed(()=>departmentsForCompany(companyId.value,departments.value))
const key=`task-draft:batch:${auth.me?.id}:${auth.me?.role}:${auth.me?.companyId}`
const epoch=sessionEpoch()
let alive=true
function persist(){if(epoch!==sessionEpoch())return;try{sessionStorage.setItem(key,JSON.stringify({source:source.value,rows:rows.value,companyId:companyId.value,host:host.value,deadline:deadline.value,locked:locked.value}))}catch{/* Reported state remains visible. */}}
function preview(){error.value='';try{rows.value=parseTaskRows(source.value).map(r=>({...r,hostDeptId:host.value,key:crypto.randomUUID(),status:'pending'}));if(!rows.value.length)error.value='表格中没有填写工作内容，未生成任务';persist()}catch(e){error.value=errorText(e)}}
async function publish(){error.value='';if(!companyId.value||!deadline.value||new Date(deadline.value).getTime()<=Date.now()||rows.value.some(r=>!r.hostDeptId||!r.title?.trim()||!r.content?.trim())){error.value='请核对公司、每条主办部门、任务内容及未来的截止时间';return}busy.value=true;locked.value=true;persist();try{for(const row of rows.value){if(!alive)break;if(row.taskId)continue;try{const result=await api.post('/tasks',{title:row.title,content:row.content,companyId:companyId.value,hostDeptId:row.hostDeptId,collaboratorDeptIds:[],priority:'NORMAL',deadline:deadline.value},{headers:{'Idempotency-Key':row.key}});row.taskId=result.id;row.status='created';row.error=''}catch(e){row.status='failed';row.error=errorText(e)}persist()}}finally{busy.value=false}}
onMounted(async()=>{if(!['GROUP_LEADER','DIVISION_LEADER','COMPANY_LEADER'].includes(auth.me?.role??'')){error.value='当前岗位无权批量布置任务';return}try{const [d,c]=await Promise.all([api.get('/organization/departments'),api.get('/organization/collaboration-departments')]);departments.value=listItems(d);directory.value=listItems(c);const raw=sessionStorage.getItem(key);if(raw){const saved=JSON.parse(raw);source.value=saved.source??'';rows.value=saved.rows??[];companyId.value=saved.companyId;host.value=saved.host;deadline.value=saved.deadline??'';locked.value=!!saved.locked}}catch(e){error.value=errorText(e)}})
onBeforeUnmount(()=>{alive=false;persist()})
</script>
<template>
 <section class="page-heading"><div><h1>批量布置任务</h1><p class="muted">从 Excel 复制表头和工作事项，逐条核对后生成待确认任务。</p></div><router-link to="/tasks"><el-button>返回任务中心</el-button></router-link></section>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <section class="panel"><h2>选择发布范围</h2><el-form label-position="top"><div class="form-grid"><el-form-item label="所属公司" required><el-select v-model="companyId" :disabled="locked" @change="host=null;rows=[]"><el-option v-for="c in companies" :key="c.id" :value="c.id" :label="c.name"/></el-select></el-form-item><el-form-item label="默认主办部门" required><el-select v-model="host" :disabled="locked"><el-option v-for="d in hosts" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><el-form-item label="本批截止时间" required><el-date-picker v-model="deadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" :disabled="locked"/></el-form-item></div><el-form-item label="表格内容"><el-input v-model="source" type="textarea" :rows="7" :disabled="locked" placeholder="在 Excel 中选中表头与数据行，复制后粘贴到这里。须包含工作内容列。"/></el-form-item><el-button :disabled="locked" @click="preview">解析并预览</el-button></el-form></section>
 <section v-if="rows.length" class="panel batch-preview"><div class="panel-heading"><h2>逐条核对 共 {{ rows.length }} 项</h2><el-button type="primary" :loading="busy" :disabled="rows.every(r=>r.taskId)" @click="publish">{{ locked?'重试未完成项':'创建待确认任务' }}</el-button></div><p class="notice">每条事项创建为草稿，仍须由领导核对并确认分配。表格原有的推进情况和协调问题作为内容保留，不会伪造系统处理历史。原文时间要求不会自动替代上方截止时间。</p><article v-for="row in rows" :key="row.key" class="scope-editor"><p class="muted">原表第 {{ row.sourceRow }} 行</p><el-input v-model="row.title" :disabled="locked" aria-label="任务标题" maxlength="200"/><el-input v-model="row.content" :disabled="locked" type="textarea" :rows="4" aria-label="任务内容" maxlength="10000"/><el-select v-model="row.hostDeptId" :disabled="locked" placeholder="主办部门"><el-option v-for="d in hosts" :key="d.id" :label="d.name" :value="d.id"/></el-select><router-link v-if="row.taskId" :to="'/tasks/'+row.taskId">已创建 查看并确认任务</router-link><p v-if="row.error" role="alert">{{ row.error }}</p></article></section>
</template>
<style scoped>.batch-preview{margin-top:24px}.scope-editor{display:grid;gap:12px}.scope-editor p{margin:0}.el-date-editor{max-width:100%}</style>
